/**
 * @description Connection Type "Apex Auth": runs the connection's Auth Class (IntegrationHub.IConnectionAuth) on a
 * request, resends once after a 401, and knows how many callouts a send needs, so a send job never goes past the
 * callout limit. A missing class or an error of the class is permanent; a callout error or timeout at its token URL is
 * temporary (auto-retry applies). On the screens an Apex Auth connection shows that its login header is added at send time (hidden).
 * @group Integration Hub
 */
public with sharing class IntegrationHubConnectionAuth {

    /** @description Callouts one Apex Auth send may need: login, send, login again after a 401, resend. */
    public static final Integer CALLOUTS_APEX_AUTH = 4;
    /** Time a send job may spend on callouts (milliseconds), below the 120-second callout limit of a transaction. */
    private static final Long BUDGET_MS = 110000;
    /** Callouts always left free in a send job, below the 100-callout limit. */
    private static final Integer CALLOUT_MARGIN = 2;

    /**
     * @description The Auth Class is missing, cannot be created or failed with an error of its own. The send fails
     * (permanent, never retried automatically).
     */
    public virtual class LoginException extends Exception {}

    /**
     * @description The Auth Class could not reach its token URL (a callout error or timeout), or no callout was left in
     * this job for the send. The send fails as a temporary failure, so auto-retry applies where the event allows it.
     */
    public class LoginUnavailableException extends LoginException {}

    /**
     * @description True when the connection logs in with its Auth Class. A blank Connection Type is Named Credential.
     * @param conn the connection (Connection_Type__c read; may be null)
     * @return whether it is Apex Auth
     */
    public static Boolean isApexAuth(IH_Connection__c conn) {
        return conn != null && conn.Connection_Type__c == IntegrationHub.CONNECTION_APEX_AUTH;
    }

    /**
     * @description Callouts one send through this connection may make.
     * @param conn the connection
     * @return 4 for Apex Auth, otherwise 1
     */
    public static Integer calloutsPerSend(IH_Connection__c conn) {
        return isApexAuth(conn) ? CALLOUTS_APEX_AUTH : 1;
    }

    /**
     * @description Whether one more send fits in this job: its callouts (an Apex Auth send: login, send, login again,
     * resend) plus a small margin stay within the callout limit, counted from the callouts this job has really made,
     * and its timeout within the time budget. The Sender chains the rest to the next job.
     * @param d the delivery
     * @param elapsedMs time already spent on sends in this job (milliseconds)
     * @param calloutLimit the callout limit to use; null for Limits.getLimitCallouts() (never above it)
     * @return true when it may be sent now
     */
    public static Boolean fitsInJob(IntegrationHubCallout.Delivery d, Long elapsedMs, Integer calloutLimit) {
        Integer callouts = calloutsPerSend(d.conn);
        Integer limitNow = calloutLimit == null ? Limits.getLimitCallouts() : Math.min(calloutLimit, Limits.getLimitCallouts());
        return elapsedMs + d.timeoutMs() <= BUDGET_MS && Limits.getCallouts() + callouts + CALLOUT_MARGIN <= limitNow;
    }

    /**
     * @description Sends a request through the connection. Named Credential: one callout. Apex Auth: the Auth Class
     * adds its login first; after a 401 it logs in again (refresh = true) and the request is resent once, when two more
     * callouts fit within the limit. A send is never made past the callout limit: when an Auth Class used up the
     * callouts, LoginUnavailableException (temporary) is thrown instead.
     * @param req the request
     * @param conn the connection
     * @param eventKey the event key (for the Auth Class)
     * @return the answer
     */
    public static HttpResponse sendThrough(HttpRequest req, IH_Connection__c conn, String eventKey) {
        if (!isApexAuth(conn)) {
            return new Http().send(req);
        }
        IntegrationHub.AuthContext ctx = new IntegrationHub.AuthContext();
        ctx.request = req;
        ctx.connection = conn;
        ctx.eventKey = eventKey;
        authorizeOrThrow(ctx);
        requireCallouts(1);
        HttpResponse res = new Http().send(req);
        if (res.getStatusCode() == 401 && Limits.getCallouts() + 2 <= Limits.getLimitCallouts()) {
            ctx.refresh = true;
            authorizeOrThrow(ctx);
            requireCallouts(1);
            res = new Http().send(req);
        }
        return res;
    }

    /* The Auth Class may have made more callouts than reserved: never call past the limit (that cannot be caught). */
    private static void requireCallouts(Integer needed) {
        if (Limits.getCallouts() + needed > Limits.getLimitCallouts()) {
            throw new LoginUnavailableException('No callout was left in this send job after the login of the Auth Class.');
        }
    }

    /**
     * @description Runs the Auth Class of an Apex Auth connection on the request. Does nothing for a Named Credential
     * connection. On a refresh the cached token is forgotten first.
     * @param ctx the request, the connection, refresh and the event key
     * @return null when the login header was added (or none is needed); otherwise the problem in plain words
     */
    public static String runAuthClass(IntegrationHub.AuthContext ctx) {
        try {
            authorizeOrThrow(ctx);
            return null;
        } catch (LoginException e) {
            return e.getMessage();
        }
    }

    /*
     * Runs the Auth Class. A missing or invalid class, or an error of the class itself: LoginException (permanent). A
     * callout error or timeout while it logs in (the token URL is down or slow): LoginUnavailableException (temporary).
     */
    private static void authorizeOrThrow(IntegrationHub.AuthContext ctx) {
        IH_Connection__c conn = ctx == null ? null : ctx.connection;
        if (!isApexAuth(conn)) {
            return;
        }
        IntegrationHub.IConnectionAuth auth = authClassOf(conn);
        if (ctx.refresh == true) {
            IntegrationHubTokenCache.removeToken(conn.Id);
        }
        try {
            auth.authorize(ctx);
        } catch (Exception e) {
            String message = 'Auth class ' + conn.Auth_Class__c.trim() + ' could not log in: ' + e.getMessage();
            LoginException failure = new LoginException(message);
            if (isCalloutProblem(e)) {
                failure = new LoginUnavailableException(message);
            }
            throw failure;
        }
    }

    /* The Auth Class of an Apex Auth connection; LoginException when it is blank, missing or not an auth class. */
    private static IntegrationHub.IConnectionAuth authClassOf(IH_Connection__c conn) {
        if (String.isBlank(conn.Auth_Class__c)) {
            throw new LoginException('Connection ' + conn.Name + ' is Apex Auth but has no Auth Class.');
        }
        try {
            return authInstance(conn.Auth_Class__c.trim());
        } catch (Exception e) {
            throw new LoginException(e.getMessage());
        }
    }

    /**
     * @description True when the exception, or the one it wraps, is a CalloutException (connection error or timeout).
     * @param e the exception
     * @return whether it is a callout problem
     */
    @TestVisible
    private static Boolean isCalloutProblem(Exception e) {
        return e instanceof CalloutException || e?.getCause() instanceof CalloutException;
    }

    /**
     * @description The Auth Class as an IntegrationHub.IConnectionAuth.
     * @param className the class name
     * @return the instance
     */
    @TestVisible
    private static IntegrationHub.IConnectionAuth authInstance(String className) {
        Type t = Type.forName(className);
        if (t == null) {
            throw new IntegrationHub.HubException('Auth class ' + className + ' was not found. Check the Auth Class on the connection.');
        }
        Object instance;
        try {
            instance = t.newInstance();
        } catch (Exception e) {
            throw new IntegrationHub.HubException('Auth class ' + className + ' could not be created: ' + e.getMessage());
        }
        if (!(instance instanceof IntegrationHub.IConnectionAuth)) {
            throw new IntegrationHub.HubException('Auth class ' + className + ' does not implement IntegrationHub.IConnectionAuth.');
        }
        return (IntegrationHub.IConnectionAuth) instance;
    }

    /**
     * @description The value shown for the Authorization header of an Apex Auth connection.
     * @param conn the connection
     * @return e.g. "added by PartnerAuth at send time (hidden)"
     */
    public static String hiddenLine(IH_Connection__c conn) {
        String className = conn?.Auth_Class__c;
        return 'added by ' + (String.isBlank(className) ? '(no Auth Class)' : className.trim()) + ' at send time (hidden)';
    }
}
